"""Create a one-file native Roblox gallery preview; no secondary downloads required."""
from __future__ import annotations
import argparse
import hashlib
import json
import build

def preview():
    library,manifest=build.bundle()
    gallery=(build.ROOT/'examples/component-gallery/init.luau').read_text(encoding='utf-8')
    source=('--!nonstrict\n'
        '-- MattLib interactive preview. Generated by scripts/build_preview.py.\n'
        '-- Includes the complete framework and gallery; returns an app with Destroy().\n'
        'local MattLib=(function()\n'+library+'\nend)()\n'
        'local runGallery=(function()\n'+gallery+'\nend)()\n'
        'return runGallery(MattLib)\n')
    metadata={'bundle_sha256':manifest['bundle_sha256'],'preview_sha256':hashlib.sha256(source.encode()).hexdigest(),
        'bytes':len(source.encode()),'entrypoint':'Preview.lua','network_requests_inside_preview':0}
    return source,metadata

def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    args=parser.parse_args()
    source,metadata=preview()
    target=build.ROOT/'Preview.lua'
    metadata_path=build.ROOT/'dist/preview-manifest.json'
    metadata_text=json.dumps(metadata,indent=2,sort_keys=True)+'\n'
    if args.check:
        if not target.exists() or target.read_text(encoding='utf-8')!=source or not metadata_path.exists() or metadata_path.read_text()!=metadata_text:
            raise SystemExit('Preview is stale; run python scripts/build_preview.py')
        print('Verified self-contained MattLib preview')
    else:
        target.write_text(source,encoding='utf-8',newline='\n')
        metadata_path.write_text(metadata_text,encoding='utf-8',newline='\n')
        print(f'Built Preview.lua: {metadata["bytes"]:,} bytes; no internal network requests')

if __name__=='__main__': main()
